insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, seo_title, seo_description, emotion_tag, nearby_attractions, nearby_lodging)
values
  ('수원 화성 순교성지', '순교성지', '수원', '경기', '경기도 수원시 팔달구 정조로 780', NULL, '조선시대 천주교 신자들이 순교한 역사적 장소로 신앙의 증거지입니다.', NULL, NULL, NULL, '수원 화성, 행궁, 화성 행궁, 방화수류정, 화성어차', '수원 교구 피정센터, 화성 관광호텔, 팔달구 모텔촌'),
  ('절두산 순교성지', '순교성지', '서울', '서울', '서울시 마포구 토정로6 (합정동)', '양화진 나루터 위 잠두봉. 이곳은 원래 한강의 빼어난 경관으로 유명했지만, 1866년 병인박해 때 수많은 천주교인이 이곳에서 참수되면서 ''절두산(切頭山)''이라는 비극적인 이름을 얻었다. 28위 성인의 유해를 모신 성해실, 순교 관련 유물을 전시하는 박물관, 한강을 내려다보는 야외 전시장이 있다. 합정역에서 도보 5분, 한강 자전거길과도 연결되어 접근성이 뛰어나다. 특히 해질녘 한강 너머로 지는 노을과 순교자 동상의 실루엣이 어우러지는 풍경은 사진작가들의 단골 촬영 포인트다.', '1866년 병인박해 때 다수의 천주교인이 참수된 곳. 28위 성인의 유해 안치. ''서울 순례길'' 3코스(일치의 길) 구간.', '절두산 순교성지 - 잘린 머리의 산, 한강의 신앙 언덕', '서울 마포 절두산 순교성지, 병인박해 순교지이자 28위 성인 유해 안치. 한강 노을과 어우러지는 촬영 명소, 서울 순례길 3코스.', NULL, '한강공원 자전거길, 합정역 일대', '마포 피정의 집, 합정동 비즈니스 호텔, 홍대 인근 게스트하우스'),
  ('해미순교성지', '순교성지', '대전', '충남', '충남 서산시 해미면 성지1로 13', '서산 해미읍성에서 서쪽으로 1km. 논밭 사이로 고요하게 자리한 이 땅 아래에는 이름조차 남기지 못한 천 명 넘는 순교자가 잠들어 있다. 1866년 병인박해가 시작되자 충청도 곳곳에서 붙잡힌 신자들이 해미읍성으로 끌려왔다. 옥에 갇히고, 고문당하고, 끝내 이곳 해미천변에서 생매장당했다. 죽음을 앞둔 이들이 부르짖은 예수 마리아는 마을 사람들의 귀에 여수 머리로 들렸고, 이곳은 여숫골이라 불리게 되었다. 2014년 프란치스코 교황이 이곳을 찾아 무명 순교자들을 기렸다. 700석 규모의 대성당, 순교자 유해를 모신 묘역, 처형이 이뤄진 진둠벙까지 — 성지를 한 바퀴 도는 것만으로 조선 후기 박해의 참혹함과 믿음의 장엄함이 동시에 전해진다.', '병인박해(1866) 최대 규모 순교지. 이름이 밝혀진 순교자 179명 포함 무명 순교자 1,000명 이상 추정. 2014년 프란치스코 교황 방문지(아시아청년대회 폐막미사).', '해미순교성지 - 여숫골, 천 명의 이름 없는 믿음', '충남 서산 해미순교성지, 병인박해 최대 순교지이자 2014년 프란치스코 교황 방문지. 여숫골 생매장터와 해미읍성을 함께 둘러보는 순례 코스.', '치유', '해미읍성(사적 제116호, 도보 15분) — 순교자 머리채를 묶었던 회화나무, 옥터', NULL),
  ('솔뫼성지', '순례길', '대전', '충남', '충남 당진시 우강면 솔뫼로 132', '당진 우강면, 내포 평야 한가운데 소나무 숲이 우거진 낮은 동산. 솔뫼라는 이름 그대로다. 이 소나무 아래에서 1821년 한국 최초의 사제 김대건 안드레아가 태어났다. 증조부 김진후, 작은할아버지 김종한, 아버지 김제준까지 4대에 걸쳐 순교자를 배출한 집안이다. 열다섯 소년이었던 김대건은 이곳을 떠나 마카오로 건너갔고, 한국인 첫 사제가 되어 돌아왔으나 스물다섯의 나이에 새남터에서 순교했다. 복원된 생가 앞마당에는 2014년 이곳을 찾은 프란치스코 교황의 기도하는 모습을 형상화한 조각이 서 있다.', '한국 최초의 사제 김대건 안드레아 신부 탄생지. 4대에 걸친 순교자 배출 가문(증조부·작은할아버지·부친·당고모). 국가 사적 제529호, 연평균 방문객 40만 명 이상.', '솔뫼성지 - 한국 최초 사제 김대건 신부 탄생지', '충남 당진 솔뫼성지, 김대건 안드레아 신부가 태어난 소나무 숲. 4대 순교자 가문의 이야기와 국가 사적 제529호 순례지.', '새출발', '버그내순례길(13.3km)로 합덕성당·신리성지와 연결', NULL),
  ('여사울성지', '순례길', '대전', '충남', '충남 예산군 신암면 신종리', '내포의 사도 이존창 루도비코의 생가터. 이존창은 1784년 한국 최초의 세례자 이승훈에게 세례를 받은 뒤 내포 지방에 천주교를 전파한 인물이다. 1801년 신유박해 때 공주 감영에서 순교했다. 그의 전교 활동으로 내포 지방은 한국 천주교의 요람이 되었다.', '내포의 사도 이존창 루도비코 생가터. 내포 지방 천주교 전파의 출발점, 1801년 신유박해 순교.', '여사울성지 - 내포의 사도 이존창의 생가터', '충남 예산 여사울성지, 내포 지방에 천주교를 전파한 이존창 루도비코의 생가터.', '위로', NULL, NULL),
  ('갈매못 순교성지', '순교성지', '대전', '충남', '충남 보령시 오천면 오천해안로 610', '보령 오천 해안가, 서해 바다가 내려다보이는 언덕 위에 조개껍데기 모양의 지붕을 얹은 성당이 서 있다. 승리의 성모성당. 이 작고도 아름다운 성당 아래 모래사장에서 1866년 3월 30일, 다섯 명이 군문효수형을 받았다. 제5대 조선교구장 다블뤼 주교, 오매트르 신부, 위앵 신부, 회장 황석두 루카와 신학당의 장주기 요셉. 성당 문을 열면 제대 뒤 스테인드글라스가 시선을 사로잡는다. 미닫이로 된 이 유리문을 열면 그날 성인들이 마지막으로 바라보았을 서해가 펼쳐진다.', '1866년 병인박해, 다블뤼 주교 등 5위 모두 성인으로 시성. 한양에서 먼 이곳까지 끌려와 처형된 특수한 배경(고종비 간택 예정으로 서울 근처 처형 회피).', '갈매못 순교성지 - 다섯 성인의 마지막 기도', '충남 보령 갈매못 순교성지, 다블뤼 주교 등 5위 성인이 순교한 서해안 성지. 조개 지붕 승리의 성모성당과 십자가의 길 14처.', '평온', '서해안 드라이브 코스와 연계', NULL),
  ('성거산성지', '순례길', '대전', '충남', '충남 천안시 서북구 입장면 위례산길 394', '해발 500m 성거산 정상 부근, 1860~1920년대 7개 교우촌이 산재했던 곳. 병인박해 때 주변 6개 교우촌에서 23명이 순교했다. 소학골 교우촌 터에는 초가 3채가 복원되어 옛 교우촌 풍경을 재현하고 있다. 봄·가을이면 야생화와 단풍이 어우러지는 산간 성지로, 한 번 순례를 온 이들은 꼭 다시 오고 싶어 하는 곳이라 불린다.', '해발 500m 산간 교우촌 터, 7개 교우촌 중 6곳에서 23명 순교. 한국 두 번째 사제 최양업 신부 가문과 연관(백부가 서덕골 교우촌 거주).', '성거산성지 - 산 위의 교우촌, 야생화 순례길', '충남 천안 성거산성지, 해발 500m 산간에 자리한 7개 교우촌 터. 야생화와 단풍이 아름다운 산간 순례 성지.', '평온', NULL, NULL),
  ('황새바위 순교성지', '순교성지', '대전', '충남', '충남 공주시 왕릉로 118', '공주 시내에서 금강을 건너기 직전, 공산성을 마주한 언덕 위에 높이 13.8미터의 순교탑이 우뚝 서 있다. 1791년부터 약 100년간, 충청도 전역에서 체포된 천주교 신자들이 공주 감영으로 끌려와 이 언덕에서 처형당했다. 이름이 밝혀진 순교자만 248위. 그중 손자선 토마스 성인은 관장이 살을 물어뜯어 신앙을 증거하라고 명하자 주저 없이 제 살을 물어뜯었다. 순교탑 아래 돌무덤 경당에는 248위의 이름이 새겨져 있고, 광장의 12개 빛돌은 이름 없는 순교자들의 묘비이자 12사도의 상징이다.', '1791~1890년대 약 100년간 이어진 충남 최대 규모 순교지. 신원 확인된 순교자만 248위, 충청·전라·경기 등 전국 각지 출신 포함.', '황새바위 순교성지 - 100년, 248개의 이름', '충남 공주 황새바위 순교성지, 100년간 248위가 순교한 충남 최대 규모 순교지. 공산성과 함께 도는 반나절 코스.', '치유', '공산성(유네스코 세계문화유산)과 도보 연계', NULL),
  ('공세리성지성당', '주교좌성당', '대전', '충남', '충남 아산시 인주면 공세리성당길 10', '아산만 방조제를 건너 야트막한 언덕을 오르면 350년 된 고목 세 그루가 먼저 반긴다. 그 너머로 붉은 벽돌의 고딕 첨탑이 솟아 있다. 조선시대 40개 마을의 조세를 보관하던 창고 터에 세워진 이 성당은 1922년 완공된 근대 건축의 보석이다. 봄이면 진입로 벚나무에 구름이 내려앉고, 언덕 위 꽃잔디가 분홍빛 바다를 이룬다. 6·25전쟁 때 8대 주임 뷜토 오 신부는 양떼를 두고 목자가 떠날 수 없다며 피난을 마다했다.', '2005년 한국관광공사 선정 대한민국에서 가장 아름다운 성당. 1922년 완공 고딕 성당, 병인박해 순교자 3인 안장, 6·25전쟁 때 뷜토 오 신부 납북·순교.', '공세리성지성당 - 대한민국에서 가장 아름다운 성당', '충남 아산 공세리성지성당, 2005년 한국관광공사 선정 가장 아름다운 성당. 1922년 고딕 건축과 봄철 벚꽃길, 성지박물관.', '감사', '아산만 방조제 드라이브 코스', NULL),
  ('신리성지', '순례길', '대전', '충남', '충남 당진시 합덕읍 신리', '제5대 조선교구장 다블뤼 주교가 은거하며 사목 활동을 하던 곳. 초가집으로 복원된 주교관이 남아 있으며, 병인박해 때 다블뤼 주교가 이곳에서 체포되어 보령 갈매못에서 순교했다. 조선의 카타콤바라 불리는 이 성지는 2024년 대대적 리뉴얼을 거쳐 담장을 낮추고 힐링 공간으로 거듭났다.', '다블뤼 주교 은거지이자 체포지, 조선의 카타콤바로 불림. 버그내순례길 출발점, 매년 5월·10월 대전교구 주최 도보성지순례 개최.', '신리성지 - 조선의 카타콤바', '충남 당진 신리성지, 다블뤼 주교의 은거지이자 체포지. 초가 주교관과 한옥 수녀원, 순례객을 위한 힐링 공간.', '평온', '버그내순례길(13.3km)로 합덕성당·솔뫼성지 연결', NULL),
  ('천주교 대흥동 교회 (대흥동 성당)', '주교좌성당', '대전', '충남', '대전광역시 중구 대흥동', '두 손을 모아 하늘을 향한 형상. 1962년 완공 당시 대전 시내에서 가장 높은 건물은 성당이었다. 지금도 49.8m 종탑은 원도심 한복판에 서서, 도시가 그 주위로 자라나는 동안 자기 자리를 지켜왔다. 정면 캐노피에 가려 쉽게 지나치지만, 고개를 들면 열두 사도 부조상이 성당을 지키고 있고, 그 위 스테인드글라스는 오스트리아에서 정통 기법을 배운 이남규 화백의 작품이다. 정문을 지나 소나무 아래에는 아들을 안은 어머니, 피에타상이 조용히 서 있다.', '1962년 완공, 국가등록문화재 제43호(2014년 등록). 대전 원도심을 대표하는 근대 건축 유산, 완공 당시 대전 시내 최고층 건물.', '대흥동성당 - 대전 원도심의 근대 건축 유산', '대전 중구 대흥동성당(천주교 대흥동 교회), 1962년 완공 국가등록문화재 제43호. 12사도 부조상과 이남규 화백의 스테인드글라스.', '감사', NULL, NULL),
  ('서소문 밖 네거리 순교성지', '순교성지', '서울', '서울', '서울시 중구 칠패로 5 (중림동)', '서울역에서 도보로 10분, 충정로역에서 5분. 수많은 직장인이 오가는 서울 도심 한복판에 조용하고도 깊은 이야기를 품은 공간이 있다. 서소문 밖 네거리. 조선 시대 이곳은 공식 처형장이었고, 1801년 신유박해부터 1866년 병인박해에 이르기까지 44위의 성인과 27위의 복자, 수많은 무명 순교자가 이곳에서 신앙을 증거했다. 2019년 개관한 서소문성지 역사박물관은 지하로 내려가는 구조 자체가 하나의 순례 여정이다. 전시실을 지나 하늘광장에 도달하면, 지하에서 올려다보는 하늘이 마치 순교자들이 마지막으로 바라보았을 그 하늘처럼 아득히 높다.', '1801년 신유박해~1866년 병인박해까지 44위 성인·27위 복자가 순교한 단일 장소 기준 한국 천주교 최대 순교지. 2018년 교황청 공인 서울 순례길 핵심 구간.', '서소문성지 역사박물관 - 도심 한복판 최대 순교지', '서울 중구 서소문성지, 44위 성인·27위 복자가 순교한 한국 최대 단일 순교지. 2019년 개관한 지하 역사박물관과 하늘광장.', '치유', '중림창고(카페골목, 도보 3분), 약현성당(도보 5분)', NULL),
  ('새남터순교성지', '순교성지', '서울', '서울', '서울시 용산구 이촌로 80-1', '한양성 밖 남쪽 한강변, 노들이라 불리던 이 모래 벌판은 조선 시대 군사 연무장이자 중죄인 처형장이었다. 1801년부터 1866년까지 한국 최초의 사제 김대건 안드레아를 비롯해 11명의 성직자가 이곳에서 순교했다. 평신도의 순교지인 서소문과 대비하여 사제들의 순교지로 불린다. 현재의 새남터순교성지 성당은 1967년 건립된 순교기념 성당으로, 성당 입구의 삶은 순교입니다. 순교는 사랑입니다라는 글귀가 방문자의 마음을 먼저 울린다.', '1801~1866년, 한국 최초 사제 김대건 안드레아 포함 11명의 성직자가 순교한 사제들의 순교지.', '새남터순교성지 - 사제들의 순교지, 한강변의 기도', '서울 용산 새남터순교성지, 김대건 안드레아 신부 등 11명의 성직자가 순교한 한강변 성지.', '치유', NULL, NULL),
  ('당고개순교성지', '순교성지', '서울', '서울', '서울시 용산구 원효로 2가', '1839년 기해박해가 거의 끝나가던 12월, 설날 대목장을 앞둔 서소문 상인들의 요청으로 처형 장소가 이곳 당고개로 옮겨졌다. 10명의 순교자 중 9명이 성인으로 시성된 의미 깊은 곳이다.', '1839년 기해박해 마지막 순교지. 10명 중 9명이 성인으로 시성.', '당고개순교성지 - 기해박해의 마지막 피', '서울 용산 당고개순교성지, 1839년 기해박해 마지막 순교지. 앵베르 주교 등 9위 성인의 순교지.', '위로', NULL, NULL),
  ('명동대성당', '주교좌성당', '서울', '서울', '서울시 중구 명동길 74', '1898년 완공된 한국 최초의 고딕 양식 벽돌 성당. 높이 47m의 종탑은 서울 도심의 상징적 랜드마크이자, 1987년 민주화 운동의 성지이기도 하다. 지하에는 한국 천주교 초대 주교의 유해가 안장된 지하 성당이 있다. 명동 쇼핑거리 한복판에서 골목 하나를 올라가면 갑자기 펼쳐지는 고요한 공간. 회색 벽돌 하나하나에 깃든 120년의 시간을 느끼며 성당 내부에 들어서면, 스테인드글라스를 통해 쏟아지는 빛이 경건함을 선사한다.', '1898년 준공, 한국 최초 고딕 양식 벽돌 성당. 사적 제258호. 1987년 민주화 운동의 성지이기도 함.', '명동대성당 - 한국 천주교의 심장, 120년 고딕의 위엄', '서울 중구 명동대성당, 1898년 완공 사적 제258호. 한국 최초 고딕 벽돌 성당이자 서울 도심의 랜드마크.', '감사', NULL, NULL),
  ('약현성당 (중림동성당)', '주교좌성당', '서울', '서울', '서울시 중구 청파로 447-1 (중림동)', '1892년 준공된 약현성당은 명동성당보다 6년 앞서 세워진 한국 최초의 서양식 벽돌 성당이다. 서소문 순교지가 한눈에 내려다보이는 언덕 위에 자리해, 순교자들에 대한 추모의 의미를 더한다. 붉은 벽돌의 로마네스크 양식이 소박하면서도 아름답다.', '1892년 준공, 명동성당보다 6년 앞선 한국 최초의 서양식 벽돌 성당. 사적 제252호.', '약현성당 - 서소문을 내려보는 최초의 서양식 성당', '서울 중구 약현성당(중림동성당), 1892년 준공 사적 제252호. 명동성당보다 앞선 한국 최초 서양식 벽돌 성당.', '평온', NULL, NULL),
  ('오륜대 한국 순교자 박물관', '역사사적지', '부산', '경남', '부산광역시 금정구 오륜대로 106', '한국 천주교 순교자들의 유물과 역사를 종합적으로 전시하는 박물관. 1983년 한국 천주교 200주년을 기념해 건립되었으며, 순교자들이 남긴 유물과 박해 시대의 문서, 초기 교회 자료를 소장하고 있다. 부산·울산 지역 성지순례의 출발점이 되는 곳이다.', '1983년 한국 천주교 200주년 기념사업으로 건립된 순교자 유물 박물관. 부산교구 대표 순례지.', '오륜대 한국 순교자 박물관 - 부산 순례의 시작점', '부산 금정구 오륜대 한국 순교자 박물관, 1983년 건립된 순교자 유물 전시관. 부산·울산 성지순례 대표 출발지.', '치유', NULL, NULL),
  ('울산 죽림굴(대왕암) 순교지', '순교성지', '부산', '경남', '울산광역시 동구', '병인박해 때 관헌의 눈을 피해 해안 동굴에 숨어 살던 신자들이 끝내 발각되어 순교한 곳. 대왕암 인근 죽림굴은 오늘날에도 당시 신자들의 고단했던 은신 생활을 짐작하게 한다.', '병인박해 때 해안 동굴에 숨어 신앙을 지키다 순교한 신자들의 은신처.', NULL, NULL, NULL, NULL, NULL),
  ('기장 성지', '순례길', '부산', '경남', '부산광역시 기장군', '박해 시대 신자들이 관의 눈을 피해 모여 살던 교우촌 터. 구체적인 순교 기록은 추가 확인이 필요하지만, 부산 지역 천주교 박해사의 흔적을 보여주는 장소다.', '박해시대 교우촌 터, 신자들의 은신처.', NULL, NULL, NULL, NULL, NULL),
  ('울산 장대 순교지', '순교성지', '부산', '경남', '울산광역시', '병인박해가 한창이던 시기, 울산 장대에서 신앙을 지키던 신자 세 명이 처형되었다. 이들은 2014년 프란치스코 교황 방한 시 시복되며 성인 반열에 한 걸음 다가섰다.', '병인박해(1866) 때 울산 장대에서 3위가 순교, 2014년 시복되었다.', NULL, NULL, NULL, NULL, NULL),
  ('통영 김기량 순교지(통제영 옥터)', '순교성지', '마산', '경남', '경남 통영시 문화동 세병로 일대 (통제영 옥터)', '통영 세병관 앞 번화한 세병로 거리, 지금은 사람들의 발길이 오가는 이 자리에 한때 통제영의 옥터가 있었다. 제주 함덕리 출신 상인 김기량 펠릭스 베드로는 무역을 위해 통영을 오가다 천주교 신자임이 드러나 체포되었고, 혹독한 문초 끝에도 신앙을 버리지 않아 1867년 교수형으로 순교했다. 삼도수군통제영의 중심, 조선 해군의 심장부였던 이 거리는 아홉 명의 순교자를 낳은 신앙의 자리이기도 하다. 번잡한 거리를 걷다 잠시 멈춰 서서, 이름 없이 스러진 이들의 신앙을 되새겨본다.', '제주 출신 상인 복자 김기량 펠릭스 베드로(1816~1867)가 통영에서 체포되어 통제영 옥에서 순교한 자리. 통제영에서 모두 9명의 천주교 신자가 순교했으며, 2014년 시복되었다.', '통영 김기량 순교지 - 통제영 옥터의 기억', '경남 통영 세병관 앞 통제영 옥터, 제주 상인 복자 김기량이 순교한 자리. 삼도수군통제영의 중심에 새겨진 아홉 순교자의 신앙.', '치유', NULL, NULL),
  ('거제 윤봉문 요셉 순교성지', '순교성지', '마산', '경남', '경남 거제시 일운면 지세포3길 69-22', '거제 바다가 내려다보이는 지세포, 편백나무와 맹종죽 숲길을 따라 걷다 보면 순교자의 넋을 기리는 추모탑이 나타난다. 1888년 신앙을 전하다 체포되어 진주로 압송, 끝내 배교하지 않고 순교한 복자 윤봉문 요셉의 자리다. 협소한 산중 묘소였던 이곳은 2013년 유해를 이장하며 십자가의 길과 로사리오 기도길, 전망대를 갖춘 순례지로 새롭게 조성되었다. 숲 향기를 맡으며 천천히 오르는 산책로 끝에서, 거제의 사도라 불린 한 평신도의 삶을 만난다.', '1888년 신앙을 지키다 체포되어 진주로 압송, 순교한 복자 윤봉문 요셉(1852~1888)을 기리는 성지. 2013년 유해를 이장하며 십자가의 길, 로사리오 기도길, 전망대를 갖춘 순례지로 조성되었고 2014년 시복되었다.', '거제 윤봉문 요셉 순교성지 - 지세포 숲길의 기도', '경남 거제시 지세포, 편백숲과 맹종죽림 사이 십자가의 길을 걸으며 복자 윤봉문 요셉의 순교를 기리는 자연 친화적 순례지.', '평온', NULL, NULL),
  ('정찬문 안토니오 순교성지', '순교성지', '마산', '경남', '경남 진주시 사봉면 무촌리 (허유고개)', '진주 사봉면, 예로부터 신자들이 넘나들던 허유고개를 오르면 소박한 묘 하나가 나그네를 맞는다. 1866년 병인박해 당시 남강 백사장에서 참수된 복자 정찬문 안토니오, 목 없는 시신만 수습되어 고향 땅에 몰래 묻힌 자리다. 사봉주유소를 지나 산길을 600여 미터 오르는 짧은 걸음이지만, 걸음마다 신앙을 지키기 위해 목숨을 내놓은 한 청년의 결단이 스며 있다. 2014년 시복으로 다시 세상에 알려진 이곳은, 화려하지 않아도 깊은 울림을 주는 조용한 기도처다.', '병인박해(1866) 때 남강 백사장에서 순교한 복자 정찬문 안토니오(1822~1867)의 묘소. 목 없는 시신만 수습되어 무두묘로 불리며, 2014년 프란치스코 교황 방한 시 시복되었다.', '정찬문 안토니오 순교성지 - 허유고개의 무두묘', '경남 진주시 사봉면, 병인박해 순교자 복자 정찬문 안토니오의 묘소. 목 없는 시신이 묻힌 무두묘와 신자들이 넘던 허유고개를 만나는 조용한 순례지.', '위로', NULL, NULL),
  ('진주 문산성당', '주교좌성당', '마산', '경남', '경남 진주시 문산읍 소문길 67번길 9-4', '진주 문산읍, 한옥 기와지붕과 고딕 첨탑이 나란히 마주 선 독특한 풍경이 발길을 멈추게 한다. 1905년 소촌공소로 출발해 서부 경남 최초의 본당으로 자리 잡은 문산성당은, 1923년 지어진 한옥 성당과 1937년 세워진 고딕 양식 성당을 함께 품고 있다. 동서양 건축이 한 마당에 공존하는 모습은 국내에서도 보기 드문 풍경으로, 2002년 국가등록문화재로 지정되었다. 오래된 종탑 아래 서면, 백여 년 전 이 땅에 뿌리내린 신앙 공동체의 시간이 고요히 되살아난다.', '1905년 소촌공소에서 출발해 1913년 서부 경남 최초의 본당으로 승격. 1923년 지어진 한옥 성당과 1937년 세워진 고딕 양식 성당이 나란히 남아있는 국가등록문화재 제35호.', '진주 문산성당 - 한옥과 고딕이 함께 선 성당', '경남 진주시 문산읍, 1905년 설립된 서부 경남 최초의 성당. 한옥 성당과 고딕 성당이 나란히 자리한 국가등록문화재.', '감사', NULL, NULL),
  ('왜관 성 베네딕도 수도원', '순례길', '대구', '경북', '경북 칠곡군 왜관읍 왜관수도원길 67', '낙동강 물줄기가 굽이도는 왜관, 나지막한 담장 너머로 유럽식 수도원 건물이 자리하고 있다. 원래 함경도 원산 덕원에 있던 이 수도원은 한국전쟁 중 북한을 탈출한 독일 베네딕도회 수사들이 1952년 칠곡 땅에 다시 세운 것이다. 이후 한국 베네딕도회의 중심으로 자리 잡아 기도와 노동을 함께하는 수도 공동체의 전통을 이어가고 있으며, 분도출판사를 통해 다양한 신앙 서적을 펴내고 있다. 조용한 회랑을 거닐다 보면, 분단의 아픔을 딛고 지켜낸 신앙 공동체의 시간이 느껴진다.', '북한 덕원자치수도원구의 후계 수도원으로, 한국전쟁 중 탈출한 독일 베네딕도회 수사들이 1952년 칠곡에 재건한 한국 베네딕도회의 중심 수도원.', '왜관 성 베네딕도 수도원 - 낙동강변의 독일 수도원', '경북 칠곡군 왜관읍, 북한 덕원수도원의 후계로 1952년 재건된 한국 베네딕도회의 중심 수도원. 분도출판사를 운영하는 기도와 노동의 공동체.', '평온', NULL, NULL),
  ('계산 주교좌대성당', '주교좌성당', '대구', '경북', '대구광역시 중구 서성로 10 (계산동)', '대구 근대골목 한복판, 붉은 벽돌 첨탑이 하늘을 찌르듯 솟아 있다. 1899년 목조 성당으로 출발해 1902년 로베르 신부의 설계로 완공된 계산성당은 대구 최초의 서양식 건축물이자 경상도 천주교의 상징이다. 1950년 박정희·육영수의 결혼식이, 1951년에는 훗날 추기경이 될 김수환 신부의 서품식이 이곳에서 거행되었다. 계산성당에서 관덕정 순교기념관, 성 유스티노관, 성모당까지 이어지는 약 1.5km의 도보 순례길은 대구 근대역사 골목 투어와 함께 걷기 좋은 반나절 코스다.', '1902년 완공된 대구 최초의 서양식 고딕 벽돌 성당(사적 제290호). 박정희·육영수 결혼식(1950년), 김수환 추기경 사제 서품식(1951년)이 거행된 장소로 경상도 천주교의 상징이다.', '계산 주교좌대성당 - 대구 근대골목의 첫 서양식 성당', '대구광역시 중구, 1902년 완공된 대구 최초의 서양식 고딕 성당(사적 제290호). 김수환 추기경 서품지이자 대구 근대골목 투어의 핵심 명소.', '감사', NULL, NULL),
  ('경상감영 옥터 순교지', '순교성지', '대구', '경북', '대구광역시 중구 대안동 31-11 (경상감영공원·대안성당 일대)', '대구 도심 한복판, 지금은 시민들의 쉼터가 된 경상감영공원 자리에 한때 혹독한 감옥이 있었다. 박해 시대 경상도 각지에서 체포된 천주교 신자들이 이곳 옥에 갇혀 문초를 당했고, 최봉한 프란치스코와 김시우 알렉시오를 비롯한 7명이 끝내 옥사했다. 형이 확정된 이들은 인근 관덕정 형장으로 끌려가 처형당했으니, 경상감영과 관덕정은 한 이야기의 두 장면인 셈이다. 오늘날 대안성당이 자리한 이 일대를 걸으며, 도심 속에 스며 있는 순교의 기억을 찾아본다.', '박해시대 경상도 각지에서 체포된 천주교 신자들이 혹독한 문초를 받고 갇혀 있던 옥터. 최봉한 프란치스코, 김시우 알렉시오, 박경화 바오로, 안군심 리카르도 등 7위가 이곳에서 옥사했다.', '경상감영 옥터 순교지 - 대구 도심 속 순교의 기억', '대구광역시 중구 대안동, 박해시대 경상도 신자들이 갇혀 옥사한 감영 옥터. 관덕정 순교성지와 함께 둘러보는 대구 도심 순례지.', '치유', NULL, NULL),
  ('한티 순교성지', '순교성지', '대구', '경북', '경북 칠곡군 동명면 한티로 1', '팔공산 깊은 산자락, 한티재를 넘어야 닿는 외진 계곡에 순교자들의 이야기가 잠들어 있다. 병인박해가 몰아치던 1866년, 관의 눈을 피해 이 산골로 숨어든 신자들은 옹기를 구우며 숨죽여 신앙을 이어갔지만 끝내 발각되어 11명이 순교했다. 오늘날 한티성지에는 십자가의 길과 피정의 집, 성당이 들어서 대구대교구를 대표하는 피정 장소로 자리 잡았다. 산으로 둘러싸인 고요함 속에서, 박해를 피해 살아간 이들의 절박했던 신앙을 마주하게 된다.', '병인박해(1866) 때 11명의 신자가 순교한 산골 교우촌 터. 박해를 피해 옹기를 구우며 신앙을 지킨 비밀 신앙 공동체의 흔적이 남아 있다.', '한티 순교성지 - 팔공산 산골의 옹기 교우촌', '경북 칠곡군 동명면, 병인박해 때 11명이 순교한 산골 교우촌 터. 십자가의 길과 피정의 집을 갖춘 대구대교구 대표 피정 성지.', '평온', NULL, NULL),
  ('관덕정 순교성지', '순교성지', '대구', '경북', '대구광역시 중구 관덕정길 11 (남산2동)', '대구역에서 걸어서 15분, 회색 빌딩숲 사이로 기와지붕 누각이 불쑥 솟아 있다. 조선시대 무과 시험장이자 처형장이었던 관덕정에서는 1815년부터 1868년까지 영남 천주교인 25명이 목숨을 바쳤다. 문경·상주에서 전교회장으로 활동하다 체포된 이윤일 요한은 1867년 이곳에서 군문효수형으로 순교, 1984년 한국 103위 순교성인 중 한 명으로 시성되었다. 지하 성당의 유해 봉안 제대, 1~3층 전시, 옥상 누각의 단청 아래 알파·오메가 문양까지 — 한국 전통과 신앙이 어우러진 독특한 순례지다.', '1815년 을해박해부터 1868년까지 영남 지역 천주교인 25명이 처형되고 옥사자를 합하면 50명 이상이 순교한 조선시대 형장. 한국 103위 순교성인 중 영남 유일의 성인 이윤일 요한이 1867년 이곳에서 순교, 1986년 유해를 미리내에서 이장해 봉안했다.', '관덕정 순교성지 - 대구 도심 속 영남의 순교터', '대구광역시 중구, 영남 유일 성인 이윤일 요한이 순교한 조선시대 형장. 지하 성당과 순교자 유해, 옥상 누각 전망대를 갖춘 대구 도심 속 성지.', '치유', NULL, NULL),
  ('가실성당', '주교좌성당', '대구', '경북', '경북 칠곡군 왜관읍', '칠곡 왜관 들녘 한가운데, 붉은 벽돌 고딕 성당이 낮은 지붕들 사이로 홀로 우뚝하다. 1923년 독일 베네딕도회 선교사들의 손으로 지어진 가실성당은 경북 내륙에서 보기 드문 서양식 근대 건축으로, 경북 유형문화재로 지정되어 있다. 인근 왜관 수도원과 함께 독일 베네딕도회가 한국 땅에 뿌리내린 흔적을 고스란히 간직한 곳이다. 들판을 배경으로 한 고딕 첨탑의 실루엣은 계절마다 다른 빛을 담아, 사진을 찾는 이들의 발길이 끊이지 않는다.', '1923년 완공된 고딕 양식 성당(경북 유형문화재). 독일 베네딕도회 선교사들이 건축했으며 왜관 수도원 인근에 위치한 경북 내륙의 대표적 근대 건축 성당이다.', '가실성당 - 칠곡 들녘의 고딕 첨탑', '경북 칠곡군 왜관읍, 1923년 독일 베네딕도회가 지은 고딕 양식 성당(경북 유형문화재). 왜관 수도원과 함께 둘러보기 좋은 근대 건축 명소.', '감사', NULL, NULL),
  ('목포 산정동 순교자기념성당', '순교성지', '광주', '전남', '전남 목포시 노송길 35', '목포 개항과 함께 태어난 성당, 노송길 언덕 위에서 목포항을 내려다본다. 1897년 파리외방전교회 주교의 전라도 순방으로 설립이 결정된 산정동성당은 광주대교구의 첫 본당이자 전남 천주교의 뿌리다. 1913년 완공된 성당은 이후 여러 차례 보수를 거쳐 오늘의 모습을 완성했고, 2021년에는 로마 교황청으로부터 국내 최초로 준대성전 지위를 부여받았다. 붉은 벽돌과 우뚝한 첨탑이 목포 근대 개항장 거리와 어우러진 풍경은, 신앙과 항구 도시의 역사가 함께 걸어온 120여 년의 시간을 보여준다.', '1897년 목포 개항과 함께 설립된 광주대교구 첫 본당. 2021년 로마 교황청으로부터 국내 최초로 준대성전(Minor Basilica) 지위를 받았다.', '목포 산정동 순교자기념성당 - 개항과 함께한 전남 첫 본당', '전남 목포시, 1897년 목포 개항과 함께 설립된 광주대교구 첫 본당. 2021년 국내 최초 준대성전으로 지정된 근대 개항장의 랜드마크.', '감사', NULL, NULL),
  ('5·18 기념성당(남동성당)', '주교좌성당', '광주', '전남', '광주광역시 동구 제봉로 67', '광주 도심, 낮은 담장 너머 소박한 벽돌 성당 외벽에는 아직도 총탄 자국이 남아 있다. 1980년 5월, 계엄군의 폭력이 광주를 뒤덮던 그날 밤 김성용 신부를 비롯한 12명의 민주인사가 이 성당에 모여 수습대책위원회를 꾸렸다. 윤공희 대주교는 정부의 담화를 공개적으로 반박하며 계엄군의 만행을 규탄했고, 성당은 두려움에 떨던 시민들의 피난처가 되었다. 2005년 5·18 25주년을 맞아 남동성당은 5·18 기념성당으로 선포되었고, 이후 5월 18일은 광주대교구의 교구기념일로 제정되었다. 벽에 새겨진 총탄 자국을 마주하는 순간, 신앙과 항쟁이 함께했던 그해 오월이 되살아난다.', '1980년 5·18 민주화운동 당시 김성용 신부 등 12명의 민주인사가 수습대책위원회를 열었던 역사적 장소. 윤공희 대주교가 계엄군의 폭력을 공개 비판하며 시민들의 피난처 역할을 했고, 2005년 5·18 25주년에 5·18 기념성당으로 선포되어 매년 5월 18일이 광주대교구 기념일로 제정되었다.', '5·18 기념성당(남동성당) - 총탄 자국이 남은 오월의 성당', '광주광역시 동구, 1980년 5·18 민주화운동 당시 시민들의 피난처였던 성당. 총탄 자국이 남아있으며 매년 5월 18일 광주대교구 기념일의 중심지.', '치유', NULL, NULL),
  ('영광 순교자 기념성당', '순교성지', '광주', '전남', '전남 영광군 영광읍', '전남 영광 읍내, 순교자 기념문을 지나면 소박한 성당 마당에 순교자상이 서 있다. 조선 천주교회 초기, 유항검의 복음 전파로 영광에도 신앙 공동체가 뿌리내렸지만 1801년 신유박해가 몰아치며 이화백과 복산리 오씨가 이곳에서 처형되었다. 함께 신앙을 나누던 이들은 전주에서 순교하거나 황해도로 귀양을 떠나야 했다. 1937년 세워졌다 폐쇄된 성당은 1965년 다시 문을 열었고, 2010년 순교자 기념성당으로 지정되며 기념문과 순교자상, 기념 전시관이 차례로 세워졌다. 조용한 읍내 성당에서, 이백여 년 전 이 땅에 뿌리내렸던 첫 신앙의 흔적을 마주한다.', '1801년 신유박해 때 영광 출신 이화백과 복산리 오씨가 순교한 것을 기려 2010년 순교자 기념성당으로 지정. 유항검의 복음 전파로 형성된 초기 신앙 공동체의 흔적이다.', '영광 순교자 기념성당 - 신유박해의 첫 신앙 흔적', '전남 영광군 영광읍, 신유박해(1801) 순교자 이화백을 기리는 성당. 순교자 기념문과 기념 전시관을 갖춘 조용한 읍내 성지.', '위로', NULL, NULL),
  ('곡성 옥터 성지(곡성성당)', '주교좌성당', '광주', '전남', '전남 곡성군 곡성읍', '전남 곡성 읍내 한켠, 성당 뒤편에 조용히 자리한 옥터전시실이 130여 년 전의 아픔을 증언한다. 을해박해(1815)를 피해 경상도·강원도에서 곡성 산골로 숨어든 신자들은 옹기를 구우며 신분을 감추고 신앙을 이어갔다. 그러나 1827년 정해박해가 시작되며 다시 붙잡혔고, 곡성현 객사를 개조한 임시 감옥에 갇혀 혹독한 고문을 받았다. 대부분 배교했지만 이 막달레나와 이성지 요한 등은 끝까지 신앙을 지키다 순교했다. 130년이 지난 1957년, 광주대교구는 이 자리에 곡성본당을 세워 선조들의 신앙을 기렸다. 오늘날 성당 옥사와 십자가의 길, 성모동산이 그날의 기억을 잇는다.', '을해박해(1815)를 피해 곡성 오곡면으로 피신한 신자들이 옹기를 구우며 신앙을 지키다, 1827년 정해박해로 다시 체포되어 곡성현 객사(임시 감옥)에서 고문받고 순교한 자리. 1958년 광주대교구가 이 순교 현장에 곡성본당을 세웠다.', '곡성 옥터 성지 - 정해박해의 진원지, 곡성성당', '전남 곡성군 곡성읍, 정해박해(1827) 때 신자들이 갇혀 순교한 옥터. 곡성성당 옥사전시실에서 옹기 교우촌의 아픈 역사를 만난다.', '위로', NULL, NULL),
  ('나주 순교자 기념성당', '순교성지', '광주', '전남', '전남 나주시 (나주성당)', '나주 읍내, 성당 마당 한켠에 130여 년 전의 흔적을 담은 받침돌이 여러 개 놓여 있다. 예전 나주 진영의 군사훈련장이자 형장이었던 무학당의 흔적이다. 1872년 병인박해가 저물어가던 시기, 강영원 바오로와 유치성 안드레아는 이곳에서 얼굴에 적신 종이를 여러 겹 붙이는 백지사형으로 순교했다. 이춘화 베드로, 유문보 바오로와 함께 이들 네 순교자를 기려 세워진 나주성당은 광주대교구 내 유일한 순교터를 품고 있다. 2001년 나주초등학교에 남아있던 받침돌을 성당으로 이전해 세운 기념 구조물 앞에서, 이름이 남은 네 순교자의 신앙을 되새겨본다.', '병인박해 말기인 1872년 나주 무학당(군사훈련장이자 형장)에서 강영원 바오로, 유치성 안드레아 등이 백지사형으로 순교. 광주대교구 내 유일한 순교터로, 무학당 초석 일부가 2001년 성당 경내로 이전되어 기념 구조물로 보존되어 있다.', '나주 순교자 기념성당 - 무학당 형장의 네 순교자', '전남 나주시, 1872년 무학당 형장에서 순교한 강영원·유치성 등 네 순교자를 기리는 성당. 광주대교구 내 유일한 순교터.', '치유', NULL, NULL),
  ('황사평 성지', '순례길', '제주', '제주', '제주특별자치도 제주시 기와 5길 117-22', '제주 시내를 벗어난 자리, 넓은 들판 사이로 십자가와 비석들이 조용히 늘어서 있다. 1901년 신축교안(이재수의 난)으로 수백 명의 천주교 신자가 희생된 뒤, 1903년 프랑스와의 합의에 따라 이곳이 공동묘지로 마련되었다. 이후 별도봉 아래에 묻혀 있던 무연고 순교자들의 유해도 이곳으로 이장되었고, 제주 선교 100주년을 맞아 지금의 공원묘지로 새롭게 단장되었다. 제주 첫 순교자 김기량 베드로의 현양비, 초대 교구장의 묘를 비롯해 외국 선교사들의 공덕비가 함께 자리한다. 1977년부터 해마다 열리는 순교자 현양대회를 통해, 이곳은 제주 천주교 신앙의 뿌리를 되새기는 자리로 이어지고 있다.', '1901년 신축교안(이재수의 난) 당시 희생된 수백 명의 천주교 신자를 위해 1903년 프랑스와의 합의로 조성된 공동묘지. 제주 첫 순교자 김기량 베드로와 초대 교구장의 묘가 있으며, 1977년부터 매년 순교자 현양대회가 열린다.', '황사평 성지 - 신축교안 순교자들의 안식처', '제주특별자치도 제주시, 1901년 신축교안 희생자들을 위한 공동묘지. 제주 첫 순교자 김기량의 현양비와 초대 교구장의 묘가 있는 제주교구 순교자 현양의 중심지.', '치유', NULL, NULL),
  ('제주 관덕정', '순례길', '제주', '제주', '제주특별자치도 제주시 관덕로 19', '제주 원도심 한복판, 우뚝한 누각 하나가 오백 년이 넘는 세월을 지키고 있다. 1448년 군사 훈련을 위해 지어진 관덕정은 제주에서 가장 오래된 건물이다. 1901년, 무거운 세금과 천주교회에 대한 반감이 쌓여가던 신축교안 당시, 민군을 이끌던 이재수가 이 광장에 모여 제주성으로 향했고, 이 과정에서 수백 명의 사상자가 나왔다. 사건이 수습된 뒤에는 관련자들이 이곳에서 처형되기도 했다. 오늘날 관광객으로 붐비는 관덕정 광장을 거니며, 신앙과 지역 공동체가 맞서서 싸우던 백여 년 전의 아픈 역사를 떠올려본다.', '1448년 군사 훈련을 위해 지어진 제주 최고(最古) 건물. 1901년 신축교안(이재수의 난) 당시 민군이 이 광장에 모였고, 충돌로 수백 명의 사상자가 발생한 사건 현장이다.', '제주 관덕정 - 신축교안의 현장', '제주특별자치도 제주시, 1901년 신축교안(이재수의 난)의 중심 무대였던 제주 최고(最古)의 건물. 신앙과 지역사회가 충돌했던 근대사의 현장.', '치유', NULL, NULL),
  ('용수성지 (성 김대건 신부 제주 표착 기념관)', '역사사적지', '제주', '제주', '제주특별자치도 제주시 한경면 용수리', '제주 서쪽 끝 용수리 포구, 파도가 밀려오는 해안에 배 한 척이 놓여 있다. 1845년 한국인 최초로 사제품을 받은 김대건 안드레아 신부가 페레올 주교, 다블뤼 신부와 함께 라파엘호를 타고 귀국하던 중, 거센 풍랑에 떠밀려 이곳 용수리 해안에 닿았다. 일행은 고국 땅에서의 첫 미사를 이곳에서 올린 뒤 배를 수리해 다시 길을 떠났다. 1999년 제주교구는 이 자리를 성지로 선포하고 기념성당과 기념관을 지었으며, 고증을 거쳐 복원한 라파엘호도 함께 전시하고 있다. 다음 해 새남터에서 순교하게 될 사제가 고국 땅을 처음 밟은 그 순간을, 파도 소리와 함께 마주한다.', '1845년 중국 상해에서 사제품을 받은 한국 최초의 사제 김대건 안드레아 신부가 귀국길에 폭풍을 만나 표착한 해안. 1999년 성지로 선포되어 기념성당과 기념관, 복원된 라파엘호가 전시되어 있다.', '용수성지 - 김대건 신부의 제주 표착지', '제주특별자치도 제주시 한경면, 김대건 신부가 귀국길에 표착해 첫 미사를 올린 해안. 기념성당과 복원된 라파엘호를 만나는 성지.', '새출발', NULL, NULL),
  ('대정성지 (정난주 마리아 묘)', '순례길', '제주', '제주', '제주특별자치도 서귀포시 대정읍 동일리', '서귀포 대정, 낮은 봉분 하나가 자리잡은 묘역에 파란만장한 삶이 잠들어 있다. 정약용의 조카이자 황사영의 아내였던 정난주 마리아는 1801년 남편의 백서 사건으로 관노 신분이 되어 대정현으로 귀양을 왔다. 어린 아들을 배 모는 사람에게 맡기고 추자도에 남겨둔 채 홀로 제주 땅을 밟은 그는, 신앙의 불모지에서도 학식과 믿음으로 주위의 존경을 받으며 37년을 살다 세상을 떠났다. 피를 흘리며 순교하지는 않았지만 유배지에서 끝까지 신앙을 지킨 그의 삶을 기려, 제주교구는 그를 백색 순교자로 공경하며 1994년 이곳을 대정성지로 조성했다. 조용한 묘역 앞에서, 낯선 섬에서 홀로 신앙을 지켜낸 한 여인의 생을 되새겨본다.', '정약용의 조카이자 황사영의 부인이었던 정난주 마리아(1773~1838)가 황사영 백서 사건으로 관노가 되어 유배 온 뒤 37년간 신앙을 지키며 살다 생을 마친 묘소. 피를 흘리지 않고 신앙을 지킨 삶으로 백색 순교자로 공경받는다.', '대정성지 - 백색 순교자 정난주 마리아의 묘', '제주특별자치도 서귀포시 대정읍, 유배지에서 37년간 신앙을 지킨 정난주 마리아의 묘소. 피 흘리지 않은 순교, 백색 순교자를 기리는 성지.', '위로', NULL, NULL),
  ('청주읍성 순교성지(서운동성당)', '순교성지', '청주', '충북', '충북 청주시 상당구 서운동', '청주 원도심, 예전 읍성의 흔적을 따라가면 순교자들의 이야기가 곳곳에 남아 있다. 신유박해(1801)부터 병인박해(1866)까지, 청주진영과 남문 밖 장터, 청주옥에서 신앙을 지키다 목숨을 잃은 이들이 있었다. 2014년 프란치스코 교황 방한 시 원시보 야고보, 배관겸 프란치스코, 오반지 바오로를 비롯한 5위가 복자품에 올랐다. 1932년 다른 성당에서 분리되어 청주 첫 본당이 된 서운동성당은 오반지 바오로의 유해를 모시고 있으며, 청주진영과 장대, 옥터까지 이어지는 순례길의 출발점이기도 하다. 도심 곳곳에 남은 순교의 자리를 걸으며, 이백여 년 전 청주 신앙의 뿌리를 되돌아본다.', '신유박해(1801)부터 병인박해(1866)까지 순교자를 낸 청주 지역 순교 사적지. 2014년 시복된 원시보 야고보, 배관겸 프란치스코, 오반지 바오로 등 5위가 이곳에서 순교했다. 서운동성당은 1932년 다른 성당에서 분리된 청주 첫 본당으로, 복자 오반지 바오로의 유해를 모시고 있다.', '청주읍성 순교성지 - 서운동성당과 다섯 복자', '충북 청주시 상당구, 신유박해부터 병인박해까지 순교자를 낸 청주 도심 순례길. 서운동성당에 오반지 바오로 유해가 모셔진 청주 첫 본당.', '치유', NULL, NULL),
  ('음성 감곡면 매괴성당', '주교좌성당', '청주', '충북', '충북 음성군 감곡면', '충북 음성군 감곡면, 나지막한 언덕 위에 고딕 첨탑이 하늘을 향해 서 있다. 1896년 프랑스인 임가밀로 신부가 세운 이 성당은 충북에서 가장 먼저 지어진 성당이다. 1930년 지금의 고딕 양식으로 새로 지어진 성당은 충북 유형문화재로 지정되어 있다. 임가밀로 신부는 51년 동안 이 자리를 지키며 문맹퇴치를 위한 학교를 세워 일제강점기 아이들에게 한글을 가르쳤고, 세상을 떠나서도 성당 소제대 곁에 잠들어 있다. 성모 순례지로도 이름난 이곳에서, 낯선 땅에 평생을 바친 한 선교사의 발자취를 만난다.', '1896년 프랑스인 임가밀로 신부가 세운 충북 최초의 성당(전국 18번째). 1930년 지어진 고딕 양식 성당은 충북 유형문화재 제188호. 임가밀로 신부는 51년간 사목하며 문맹퇴치를 위한 학교를 세워 한글을 가르쳤다.', '음성 감곡면 매괴성당 - 충북 천주교의 발상지', '충북 음성군, 1896년 임가밀로 신부가 세운 충북 최초의 성당(충북 유형문화재). 51년을 헌신한 선교사의 발자취가 남은 성모 순례지.', '감사', NULL, NULL),
  ('배티 순교성지', '순교성지', '청주', '충북', '충북 진천군 백곡면 양백리', '충북 진천과 경기 안성의 경계, 서운산 자락 깊은 계곡에 배나무 고개라는 뜻의 배티가 있다. 1830년경 박해를 피해 숨은 신자들이 이룬 비밀 교우촌으로, 한국 천주교의 카타콤이라 불린다. 1850년 프랑스인 주교가 이곳에 한국 최초의 신학교를 지었으며, 한국인 두 번째 사제 최양업 토마스 신부가 배티를 근거지 삼아 전국을 걸어 다니며 신자들을 돌보고 한글 기도서를 지어 나눠주었다. 1866년 병인박해 때는 55여 명이 이곳에서 순교했다. 오늘날 성지에는 고딕 양식 기념성당과 최양업 신부 박물관, 복원된 초가 신학교, 무명 순교자 묘역이 자리해 있어, 방문객은 걸음마다 조용히 신앙의 뿌리를 만나게 된다.', '1830년경부터 형성된 비밀 교우촌으로 한국 천주교의 카타콤으로 불린다. 1850년 프랑스인 주교가 한국 최초의 신학교(조선교구 소신학교)를 설립했고, 한국인 두 번째 사제 가경자 최양업 토마스 신부가 사목 중심지로 삼았다. 1866년 병인박해 때 55여 명이 순교했다.', '배티 순교성지 - 한국 천주교의 카타콤', '충북 진천군 백곡면, 최양업 신부가 사목 중심지로 삼았던 비밀 교우촌. 한국 최초 신학교 터와 병인박해 순교자 묘역을 품은 대표 성지.', '치유', NULL, NULL),
  ('연풍 순교성지', '순교성지', '청주', '충북', '충북 괴산군 연풍면', '문경새재로 넘어가는 길목, 연풍 예전 관아 터에 순교자들의 이야기가 남아 있다. 병인박해가 몰아치던 1866년, 새재를 오가며 신앙을 나누던 충북과 경북의 신자들이 이곳 연풍현 관아에 붙잡혀 처형되었다. 영남과 충청을 연결하는 교통 요충지였던 탓에, 이 길을 오가던 이들의 신앙도 함께 스러졌다. 조용한 산골 마을을 걸으며, 새재를 넘던 예전 신자들의 발걸음과 그 끝에 놓였던 형장을 함께 떠올려본다.', '병인박해(1866) 때 연풍현 관아에서 신자들이 처형된 순교지. 새재(조령) 인근 교통 요충지로, 충북과 경북을 오가던 신자들이 체포되어 순교했다.', '연풍 순교성지 - 새재 길목의 순교지', '충북 괴산군 연풍면, 병인박해 때 연풍현 관아에서 순교한 신자들의 자리. 문경새재를 오가던 충북·경북 신자들의 신앙이 스러진 곳.', '위로', NULL, NULL),
  ('충북 보은 멘에목 순례성지', '순례길', '청주', '충북', '충북 보은군', '보은 깊은 산골, 낮게 이어지는 작은 고개를 넘으면 이름 없이 살다 간 신자들의 자리가 있다. 1827년 정해박해 기록에 처음 등장하는 이 교우촌에는 박경화 바오로와 아들 박사의 안드레아가 신앙 공동체를 이루며 살았고, 최양업 신부가 이 산골까지 찾아와 성사를 베풀었다. 2014년 프란치스코 교황 방한 당시 이 세 사람이 복자품에 올랐고, 2016년 청주교구는 이곳을 정식 성지로 지정했다. 산으로 둘러싸인 고요한 계곡을 걸으며, 오래도록 잊혔던 작은 교우촌의 신앙을 다시 만난다.', '1827년 정해박해 때부터 기록에 등장하는 산골 교우촌. 복자 박경화 바오로·박사의 안드레아 부자가 거주했고 최양업 신부가 방문해 성사를 베풀었다. 2014년 프란치스코 교황 방한 시 박경화, 박사의, 그리고 김씨 복자까지 3위가 시복, 2016년 청주교구가 성지로 지정했다.', '충북 보은 멘에목 순례성지 - 보은 산골의 작은 교우촌', '충북 보은군, 정해박해 때부터 이어진 산골 교우촌. 복자 박경화·박사의 부자를 기리는 2016년 지정 성지.', '위로', NULL, NULL),
  ('전동성당', '주교좌성당', '전주', '전북', '전북 전주시 완산구 태조로 51 (전동)', '전주 한옥마을 입구, 경기전 맞은편에 회색 벽돌 성당이 우뚝 서 있다. 전동성당은 1791년 신해박해 때 한국 천주교 최초의 순교자 윤지충 바오로와 권상연 야고보가 풍남문 밖에서 처형된 바로 그 자리에 세워졌다. 1801년에는 호남의 사도 유항검 아우구스티노가 이곳에서 능지처참형을 당했다. 1908년 착공해 1914년 완공된 로마네스크 양식 성당 내부에는 18개의 색유리창이 순교자들의 이야기를 담고 있다. 한옥마을과 경기전, 치명자산으로 이어지는 순례길의 출발점으로, 호남 천주교 역사의 상징으로 자리잡았다.', '한국 천주교 최초의 순교자 윤지충 바오로와 권상연 야고보가 1791년 신해박해 때 처형된 자리에 세워진 성당(사적 제288호). 1908년 착공, 1914년 완공된 로마네스크 양식 건축.', '전동성당 - 한국 최초 순교자의 자리', '전북 전주시 완산구, 윤지충·권상연이 순교한 자리에 세워진 로마네스크 성당(사적 제288호). 한옥마을과 어우러진 호남 천주교의 상징.', '감사', NULL, NULL),
  ('치명자산 성지', '순례길', '전주', '전북', '전북 전주시 완산구 교동 승암산(치명자산) 정상', '전주 시내를 내려다보는 승암산 정상, 순교자의 산이라는 뜻의 치명자산이 있다. 1914년 보두네 신부가 유항검 아우구스티노와 그 가족 7명의 유해를 이 산 정상에 모시면서 붙은 이름이다. 유항검과 부인 신희, 동정부부 유중철·이순이를 비롯한 일가족이 나란히 합장되어 있다. 프랑스 파리의 순교 언덕과 견주어지는 이유다. 2014년 프란치스코 교황 방한 시 이 중 5위가 시복되었다. 십자가의 길을 따라 정상까지 오르는 순례 코스는 전주 시내를 한눈에 담는 야경 명소로도 사랑받는다.', '1914년 보두네 신부가 유항검 가족 순교자 7위의 유해를 산 정상에 모시면서 치명자산(순교자의 산)으로 불리게 되었다. 프랑스 파리의 순교 언덕과 견주어 한국의 순교자 언덕으로 불리며 2014년 프란치스코 교황 방한 시 5위가 시복되었다.', '치명자산 성지 - 전주의 순교자 언덕', '전북 전주시 완산구 승암산 정상, 유항검 일가족 7위가 합장된 순교성지. 십자가의 길과 전주 야경을 함께 만나는 순례 코스.', '새출발', NULL, NULL),
  ('초남이 성지', '순례길', '전주', '전북', '전북 전주시 완산구 (바우배기)', '전주 외곽 초남이 마을, 바우배기라 불리는 자리에 호남 신앙의 뿌리가 묻혀 있었다. 이곳은 호남의 사도 유항검 가족이 신앙을 키워가던 터전으로, 호남 지역 복음 전래가 시작된 자리로 알려져 있다. 오랜 세월 사람들의 기억에서 멀어졌던 이곳은 2014년 성역화 작업이 진행되며 뜻밖의 발굴로 이어졌다. 한국 최초의 순교자 윤지충과 권상연, 그리고 윤지헌의 유해가 이곳 바우배기에서 발견된 것이다. 평범한 마을 땅속에서 다시 세상에 나온 순교자들의 흔적 앞에서, 호남 신앙의 첫 자리를 다시 한번 되새겨본다.', '호남 천주교 복음 전래의 출발점이자 유항검 가족의 신앙 터전. 2014년 바우배기 성역화 작업 중 윤지충·권상연·윤지헌의 유해가 발굴되었다.', '초남이 성지 - 호남 신앙의 첫 자리, 바우배기', '전북 전주시 완산구, 유항검 가족의 신앙 터전이자 2014년 윤지충·권상연·윤지헌 유해가 발굴된 바우배기. 호남 복음 전래의 출발점.', '위로', NULL, NULL),
  ('나바위 성지', '순례길', '전주', '전북', '전북 익산시 망성면', '금강이 내려다보이는 나바위 언덕에 한옥 지붕을 얹은 특별한 성당이 있다. 1845년 김대건 신부가 중국에서 사제품을 받고 페레올 주교, 프랑스인 신부와 함께 황산 나루터에 배를 대고 내렸다. 한국인 최초의 사제가 고국 땅을 밟으며 처음 전도를 시작한 곳이기도 하다. 1906년 시공해 이듬해 완공한 성당은 서양식 건축과 한옥 양식을 절충한 독특한 모습으로, 사적 제318호로 지정되었다. 경내에는 김대건 신부 순교 100주년에 세워진 순교비가 자리한다. 금강을 따라 불어오는 바람 속에서, 조선 땅을 처음 밟은 사제의 설렘을 상상해본다.', '1845년 김대건 신부가 중국에서 사제 서품을 받고 페레올 주교, 프랑스인 신부와 함께 황산 나루터로 상륙해 처음 전도한 자리. 1906년 착공, 1907년 완공된 성당은 한옥과 서양식 건축이 어우러진 사적 제318호.', '나바위 성지 - 김대건 신부가 첫발로 내린 성당', '전북 익산시 망성면, 김대건 신부가 사제 서품 후 처음 상륙해 전도한 자리에 세워진 한옥 양식 성당(사적 제318호).', '새출발', NULL, NULL),
  ('천호성지', '순례길', '전주', '전북', '전북 완주군 비봉면 천호성지길', '완주 비봉면, 천호산 깊은 계곡에 박해를 피해 숨어든 신자들의 자리가 있다. 기해박해(1839) 이후 이 산자락에 교우촌이 형성되었고, 병인박해 때는 이명서·손선지·정문호·한재권 네 성인이 순교했다. 산속에는 프랑스인 주교와 신부가 몸을 숨긴 채 미사를 드렸던 작은 굴, 미사굴이 지금도 남아 있다. 피정의 집과 봉안경당, 성물박물관이 들어선 오늘날의 천호성지를 걸으며, 산속 깊이 숨어 신앙을 지켰던 이들의 절박한 시간을 만난다.', '기해박해(1839) 이후 천호산 자락에 형성된 교우촌. 병인박해 때 순교한 성인 4위(이명서·손선지·정문호·한재권)와 여산 순교자 10명이 안장되어 있다. 프랑스인 주교와 신부가 숨어 미사를 드린 미사굴이 남아 있다.', '천호성지 - 미사굴에 숨은 신앙', '전북 완주군 비봉면, 기해박해 이후 형성된 천호산 교우촌. 페레올 주교가 숨어 미사를 드린 미사굴과 병인박해 순교 성인 4위를 만나는 성지.', '평온', NULL, NULL),
  ('죽산 순교성지', '순교성지', '수원', '경기', '경기도 안성시 일죽면 죽림리', '충청·전라·경상으로 갈라지는 길목, 조선시대 죽산 도호부가 있던 자리에 잊혔던 순교의 역사가 남아 있다. 넓은 관할 구역 곳곳의 교우촌에서 체포된 신자들이 죽산 도호부의 옥에 갇혀 혹독한 고문을 받은 뒤, 지금의 성지 자리에서 처형되었다. 이름이 확인된 순교자만 24명에 이른다. 고려시대 몽골군이 진을 쳤던 이진터라는 이 자리에는, 박해가 남긴 아픔을 담아 잊은 터라는 이름이 붙었다. 오가는 이들의 발길 속에 잊혀갔던 순교자들의 이름을, 오늘 다시 불러본다.', '병인박해 때 체포된 신자들이 죽산 도호부 옥사에서 고문당한 뒤 처형된 자리. 이름이 밝혀진 순교자만 24명에 이른다. 예전 지명 이진터에 박해 시기 잊은 터라는 이름이 더해졌다.', '죽산 순교성지 - 잊은 터에 새긴 스물네 이름', '경기도 안성시 일죽면, 병인박해 때 죽산 도호부에서 순교한 24명의 신자를 기리는 성지. 충청·전라·경상 교통 요지에 새겨진 신앙의 역사.', '치유', NULL, NULL),
  ('은이 성지', '순례길', '수원', '경기', '경기도 용인시 처인구', '용인 처인구 산자락, 숨겨진 동네라는 뜻의 은이마을이 있다. 이곳은 열다섯 살 소년 김대건이 1836년 모방 신부에게 세례와 첫 성체를 받은 자리이자, 신학생으로 선발되어 마카오 유학길에 오른 출발점이다. 사제가 되어 돌아온 김대건 안드레아는 이곳을 첫 사목지로 삼았고, 순교하기 전 마지막으로 공식 미사를 드린 곳도 바로 은이였다. 소년의 첫 세례부터 사제의 마지막 미사까지, 김대건 신부의 생애 전체가 이 작은 교우촌 하나에 고스란히 담겨 있다.', '숨겨진 동네라는 뜻의 교우촌. 김대건 안드레아가 1836년 모방 신부에게 세례와 첫 성체를 받았고, 15세에 신학생으로 선발되어 마카오로 떠난 곳. 사제 서품 후 첫 사목지이자 순교 전 마지막 공식 미사를 드린 곳이다.', '은이 성지 - 김대건 신부, 세례부터 마지막 미사까지', '경기도 용인시 처인구, 김대건 신부가 세례를 받고 첫 사목과 마지막 미사를 드린 교우촌. 그의 생애 전체가 담긴 수원교구 핵심 성지.', '새출발', NULL, NULL),
  ('미리내 성지', '순례길', '수원', '경기', '경기도 안성시 양성면 미산리', '안성 깊은 산골, 밤하늘 은하수를 닮았다 하여 미리내라는 이름이 붙은 마을이 있다. 1846년 새남터에서 순교한 한국 최초의 사제 김대건 안드레아 신부의 시신을, 신자 이윤봉 루가가 위험을 무릅쓰고 이곳에 몰래 묻었다. 그날 이후 이 산골 마을은 한국 천주교에서 가장 성스러운 자리 중 하나가 되었다. 1906년 세워진 성 요셉 성당은 세계에서 가장 작은 성당으로 알려져 있고, 1991년 지어진 103위 시성 기념 성당에서는 오늘도 순례 미사가 드려진다. 가을 단풍이 절정에 이르는 10월, 미리내로 향하는 길 자체가 이미 순례의 시작이 된다.', '1846년 새남터에서 순교한 성 김대건 안드레아 신부의 시신이 이윤봉 루가에 의해 비밀리 안장된 곳(한국 최초 사제 유해 최초 안장지). 1906년 세워진 성 요셉 성당은 세계에서 가장 작은 성당으로 알려져 있다.', '미리내 성지 - 김대건 신부가 잠든 은하수 마을', '경기도 안성시 양성면, 김대건 신부의 유해가 최초로 안장된 수원교구 대표 성지. 세계에서 가장 작은 성당과 가을 단풍으로 유명하다.', '치유', NULL, NULL),
  ('남한산성 순교성지', '순교성지', '수원', '경기', '경기도 광주시 남한산성면', '조선의 오랜 역사를 간직한 유네스코 세계문화유산 남한산성, 그 성벽 안쪽에 순교의 기억이 조용히 스며 있다. 병인박해가 몰아치던 시절, 체포된 천주교 신자들이 이곳으로 압송되어 옥에 갇히고 처형당했다. 산성의 웅장한 성곽과 누각을 둘러보는 트레킹 코스를 걷다 보면, 화려한 역사 유산 이면에 새겨진 신앙의 아픔과 마주하게 된다. 세계유산 탐방과 순교 성지 순례가 하나로 이어지는 독특한 자리다.', '유네스코 세계문화유산 남한산성 내에서 병인박해 때 체포된 천주교 신자들이 옥사하거나 처형된 순교지.', '남한산성 순교성지 - 세계유산 속 순교의 기억', '경기도 광주시 남한산성면, 병인박해 때 신자들이 옥사·처형된 세계문화유산 내 순교지. 산성 트레킹과 함께하는 순례.', '평온', NULL, NULL),
  ('골배마실 성지', '순례길', '수원', '경기', '경기도 용인시 처인구 (은이성지 인근)', '은이성지 동쪽 갈미봉 아래, 계곡을 따라 들어앉은 작은 마을 골배마실이 있다. 김대건 신부의 조부 김택현은 가세가 기울고 신앙을 지키기 어려워지자 가족을 이끌고 이 산골 땅으로 이주해 왔고, 아버지 김제준도 1835년부터 이곳에 자리 잡았다. 소년 김대건이 뛰놀며 유년 시절을 보낸 곳도 바로 이 계곡이었다. 지금은 조용한 산길이 된 이 마을을 걸으며, 한국 최초의 사제가 자란 어린 시절의 풍경을 그려본다.', '김대건 신부의 조부 김택현과 부친 김제준이 신앙을 지키기 위해 이주해 정착한 교우촌. 김대건 신부가 유년 시절을 보낸 곳이다.', '골배마실 성지 - 김대건 신부의 유년 마을', '경기도 용인시 처인구, 김대건 신부 가족이 신앙을 지키기 위해 정착한 산속 교우촌. 그의 유년 시절이 담긴 조용한 성지.', '평온', NULL, NULL),
  ('풍수원성당', '주교좌성당', '원주', '강원', '강원특별자치도 횡성군 서원면 유현리', '횡성 깊은 산골, 220여 년 전 박해를 피해 신자들이 찾아든 자리에 고딕 첨탑이 서 있다. 1801년 신유박해 이후 경기도 용인에서 8일간 피난처를 찾아 고생하던 신태보 베드로와 40여 명의 신자들이 이 산골에 정착하며 한국 천주교 최초의 교우촌을 이루었다. 도기를 구우며 신앙을 지키던 이들의 후손들은 1896년 정규하 신부를 맞이해 성당을 짓기 시작했고, 1907년 완공된 이 성당은 한국인 신부가 직접 설계하고 지은 최초의 성당이자 강원도 첫 본당이 되었다. 고딕 양식의 붉은 벽돌 성당 앞에 서면, 산골 교우촌에서 이어져 온 220년 신앙의 시간을 느낀다.', '1801년 신유박해 이후 신태보 베드로를 중심으로 40여 명이 정착한 한국 천주교 최초의 교우촌. 1907년 완공된 성당은 한국인 신부가 설계·건립한 최초의 성당이자 강원도 첫 성당(강원도 유형문화재 제69호).', '풍수원성당 - 한국 최초의 산골 교우촌', '강원특별자치도 횡성군, 신유박해 이후 형성된 한국 최초의 교우촌에 세워진 성당. 한국인 신부가 지은 최초의 성당이자 강원도 첫 본당(강원 유형문화재).', '평온', NULL, NULL),
  ('용소막성당', '주교좌성당', '원주', '강원', '강원특별자치도 원주시 신림면', '원주 신림면, 들판 사이로 서양식 붉은 벽돌 성당이 고요히 자리하고 있다. 1898년 신자 최석두의 초가집에서 작은 공소로 출발한 용소막성당은 풍수원·원주에 이어 강원도에서 세 번째로 세워진 성당이 되었다. 1915년 프랑스인 신부의 손으로 지금의 벽돌 성당이 완공되었고, 1986년 강원도 유형문화재로 지정되었다. 이 아름다운 근대 건축물은 원주의 자랑거리로 사랑받는다. 조용한 시골 마을에서 만나는 이 작은 성당은, 소박하지만 단단했던 초기 신앙 공동체의 시간을 보여준다.', '1898년 신자 최석두의 초가집에서 시작되어 1915년 현재 건물이 완공된 강원도 세 번째 성당(강원도 유형문화재). 풍수원성당, 원주성당에 이어 세워졌다.', '용소막성당 - 원주 들판의 붉은 벽돌 성당', '강원특별자치도 원주시 신림면, 1915년 완공된 강원도 세 번째 성당(강원 유형문화재). 원주를 대표하는 아름다운 근대 건축물이다.', '감사', NULL, NULL),
  ('배론성지', '순례길', '원주', '충북', '충북 제천시 봉양읍 배론성지길', '제천 봉양읍, 배 밑바닥처럼 깊은 계곡이라 하여 배론이라 불리는 자리가 있다. 1801년 신유박해가 일어나자 황사영은 이곳 도기장을 가장한 토굴에 8개월간 숨어 지내며, 북경 주교에게 보낼 편지 백서를 비단에 써 내려갔다. 박해의 참상과 신앙의 자유를 향한 절박한 호소가 담긴 이 편지는 조선 천주교사의 가장 극적인 기록으로 남았다. 1855년에는 한국 최초의 신학교인 성 요셉 신학당이 이곳에 세워져 한국인 성직자를 길러냈고, 한국인 두 번째 사제 최양업 토마스 신부가 이곳에 잠들어 있다. 깊은 계곡을 걸으며, 박해와 배움이 함께 새겨진 조선 천주교의 뿌리를 만난다.', '1801년 신유박해 때 황사영이 8개월간 숨어 지내며 백서를 쓴 토굴이 있는 곳. 1855년 한국 최초의 신학교 성 요셉 신학당이 세워졌고, 한국인 두 번째 사제 최양업 토마스 신부의 묘가 있다.', '배론성지 - 황사영 백서와 한국 최초 신학교', '충북 제천시 봉양읍, 황사영이 백서를 쓴 토굴과 한국 최초 신학교 터. 최양업 신부의 묘가 있는 원주교구 대표 성지.', '치유', NULL, NULL),
  ('강릉 임당동성당', '주교좌성당', '원주', '강원', '강원특별자치도 강릉시 임영로 148', '강릉 임당동, 높다란 종탑과 첨두형 아치 창문을 가진 성당이 오래된 동네를 지키고 있다. 1921년 금광리에서 시작된 강릉 본당은 여러 차례 자리를 이전한 끝에 1955년 지금의 성당을 신축하며 새 이름을 얻었다. 전쟁의 상처가 채 가시지 않은 시절 지어진 이 성당은 1950년대 강원도 성당 건축의 특징을 고스란히 간직해 국가등록문화재로 지정되었다. 정교한 몰딩과 아치 장식이 남아있는 성당 내부를 둘러보면, 전후 강원 신앙 공동체가 다시 일어서던 시간이 느껴진다.', '1921년 시작된 강릉 지역 첫 본당. 1955년 신축된 성당은 1950년대 강원도 성당 건축의 전형을 보여주는 건물로 국가등록문화재 제457호.', '강릉 임당동성당 - 전후 강원 신앙의 증언', '강원특별자치도 강릉시, 1955년 신축된 강릉 첫 본당. 1950년대 강원 성당 건축의 전형을 보여주는 국가등록문화재 제457호.', '감사', NULL, NULL),
  ('소양로 순교성지', '순교성지', '춘천', '강원', '강원특별자치도 춘천시 서면 모수물길 22번길 26', '춘천 도심에서 소양강 쪽으로 발걸음을 옮기면 조용한 순교의 언덕이 나타난다. 병인박해가 몰아치던 1866년, 강원도 곳곳에서 붙잡힌 천주교 신자들이 이곳에서 처형되었다. 소양강의 맑은 물소리를 배경으로 순교자 현양비가 고요히 서 있어, 낭만적인 호반 도시 춘천의 이면에 새겨진 신앙의 역사를 마주하게 된다. 춘천역에서 멀지 않은 거리라 도심 산책 삼아 들르기 좋은 조용한 성지다.', '병인박해(1866) 때 강원도 지역 천주교인들이 처형된 춘천 지역 순교터.', '소양로 순교성지 - 소양강변의 작은 순교 언덕', '강원특별자치도 춘천시, 병인박해 때 강원 지역 신자들이 순교한 춘천 도심 성지. 소양강변의 조용한 현양비.', '위로', NULL, NULL),
  ('화현 이벽 성지', '순례길', '의정부', '경기', '경기도 포천시 화현면 화현리', '포천 화현리, 평신도의 힘만으로 신앙 공동체를 이룩한 한국 천주교 최초의 지도자가 태어난 자리가 있다. 무반 집안 출신이던 광암 이벽은 정약전·정약용 형제와 교유하며 학문을 닦다가, 1779년 겨울 천진암에서 열린 강학회를 통해 서학과 천주교 신앙을 받아들였다. 사제 없이 평신도들 스스로 시작한 한국 천주교회에서, 이벽은 그 첫 지도자였다. 순교 후 190년 넘게 사람들의 기억에서 멀어져 있던 그의 묘는 1970년대 후반 발견되어 천진암성지로 이전되었고, 태어나고 순교한 이곳 화현리는 2023년 춘천교구에 의해 성지로 선포되었다. 가장 늦게 태어난 성지에서, 가장 처음 신앙을 일으킨 이의 자취를 만난다.', '한국 천주교회 최초의 지도자 광암 이벽 요한(1754~1785)이 태어나고 순교한 자리. 정약전·정약용과 교유하며 1779년 천진암 강학을 통해 신앙을 받아들였다. 2023년 5월 춘천교구가 성지로 선포한 가장 최근의 성지다.', '화현 이벽 성지 - 한국 천주교 첫 지도자의 고향', '경기도 포천시 화현면, 한국 천주교회 최초 지도자 이벽이 태어나고 순교한 자리. 2023년 춘천교구가 선포한 가장 최근의 성지.', '새출발', NULL, NULL),
  ('갑곶 순교성지', '순교성지', '인천', '경기', '인천광역시 강화군 강화읍 해안동로1366번길 35', '강화도 돈대 인근, 바다를 바라보는 언덕 위에 순교의 기억이 자리한다. 병인박해가 몰아치던 시절, 강화도에서 신앙을 지키던 이들이 이곳에서 생을 마감했다. 가톨릭 순교 역사를 직접 증언한 인물로 유명한 박순집 베드로의 묘가 이곳에 있으며, 인천교구 설정 50주년을 기념해 세운 영성센터가 함께 자리해 피정과 순례를 겸할 수 있다. 강화대교를 건너 만나는 첫 번째 신앙의 증거지다.', '병인박해 때 강화도에서 순교한 이들을 기리는 성지. 가톨릭 순교 역사를 증언한 박순집 베드로의 묘가 있다.', '갑곶 순교성지 - 강화 바다가 품은 신앙', '인천광역시 강화군, 병인박해 때 강화도 순교자를 기리는 성지. 박순집 베드로의 묘와 영성센터가 함께 있어 피정과 순례를 겸한다.', '치유', NULL, NULL),
  ('제물진두 순교성지', '순교성지', '인천', '경기', '인천광역시 중구 제물량로 240', '인천역 인근, 늘 바다를 향해 열려있던 포구 한자리에 순교의 기억이 새겨져 있다. 1866년 병인박해 이후 한국 최초의 영세자 이승훈 베드로의 증손자 이연구와 이균구를 비롯한 열 명이 이곳에서 처형되었다. 1845년에는 한국인 최초의 사제가 될 김대건 부제가 사제 서품을 받기 위해 이 근처 포구에서 작은 배를 타고 중국으로 떠났다. 2014년 완공된 순교기념경당은 하늘을 향해 솟아오르는 15m 높이의 높다란 건물로 순교자들의 영성을 상징한다. 조용한 포구에서, 떠나간 이들과 남은 이들의 신앙을 함께 떠올려본다.', '1866년 병인박해 이후 한국 첫 영세자 이승훈 베드로의 후손들을 비롯한 열 명이 처형된 자리. 1845년 김대건 부제가 사제 서품을 받기 위해 중국으로 떠난 포구이기도 하다.', '제물진두 순교성지 - 포구에 새겨진 신앙', '인천광역시 중구, 이승훈 베드로의 후손들을 비롯한 10명이 순교한 제물포 포구 순교지. 김대건 부제가 사제 서품을 받으러 떠난 포구이기도 하다.', '치유', NULL, NULL),
  ('답동주교좌성당', '주교좌성당', '인천', '경기', '인천광역시 중구 우현로50번길 2', '인천 차이나타운에서 가파른 계단길을 오르면 갑자기 로마네스크 양식 붉은 벽돌 건물이 눈앞에 펼쳐진다. 1889년 제물포 개항과 함께 세워진 답동성당은 한국에서 가장 오래된 서양식 성당 중 하나로, 사적 제287호로 지정되어 있다. 개항장의 이국적인 풍경과 유서 깊은 천주교 역사가 한 자리에서 어우러진다. 성당 앞에 서면 인천항이 내려다보여, 개항 당시의 분위기를 상상하게 한다. 인천역에서 도보 10분 거리라 차이나타운과 함께 둘러보기 좋다.', '1889년 제물포 개항과 함께 세워진 한국에서 가장 오래된 서양식 성당 중 하나(사적 제287호). 인천교구의 주교좌성당이자 개항장 역사를 대표하는 건축물이다.', '답동주교좌성당 - 개항장 언덕 위의 백년 성당', '인천광역시 중구, 1889년 세워진 한국 최고(最古) 서양식 성당 중 하나(사적 제287호). 인천 차이나타운과 가까운 개항장 순례지.', '감사', NULL, NULL),
  ('이승훈 베드로 성지', '순례길', '인천', '경기', '인천광역시 남동구 무네미로 143', '인천 남동구, 한국 천주교 첫 영세자의 이름을 따 이승훈베드로길이 난 자리에 기념관이 서 있다. 어린 시절 베이징 북당에서 프랑스인 신부에게 교리를 배운 이승훈은 1784년 귀국후 세례를 받아 한국 최초의 천주교 영세자가 되었다. 이후 미사와 세례를 직접 진행하며 교리를 전해 신앙 공동체의 출발을 이끌었다. 1801년 신유박해 때 순교한 뒤 인천 이 자리에 묻혔고, 2024년에는 그를 기리는 성지기념관이 새롭게 문을 열었다. 한국 천주교회의 출발점에 선 이의 이야기를, 이곳에서 만난다.', '1784년 한국 최초로 세례를 받은 이승훈 베드로(1756~1801)의 선산이 있는 성지. 1801년 신유박해 때 순교한 뒤 이곳에 묻혔다. 2024년 기념관이 건립되었다.', '이승훈 베드로 성지 - 한국 천주교 첫 영세자', '인천광역시 남동구, 한국 최초 영세자 이승훈 베드로의 선산이 있는 성지. 2024년 건립된 기념관에서 그의 생애를 만난다.', '치유', NULL, NULL),
  ('황사영 순교순례지', '순교성지', '의정부', '경기', '경기도 양주시 장흥면 부곱리 일대 (홍복산)', '양주 홍복산 자락, 오랜 세월 이름 없는 묘로 남아있던 자리가 있다. 1801년 신유박해 때 배론 토굴에서 백서를 쓴 죄로 능지처참형을 받은 황사영 알렉시오가 이곳에 묻혔다. 세월이 흘러 이 묘의 주인이 누구인지조차 사람들의 기억에서 멀어질 무렵인 1980년, 후손들이 홍복산 선영에서 오래된 봉분 하나를 조사하다 뜻밖의 유물을 발견했다. 항아리 속에는 돌로 만든 십자가와 비단 조각이 들어 있었고, 이는 이 묘의 주인이 황사영임을 증명하는 결정적 단서가 되었다. 조용한 산자락에서, 목숨을 걸고 진실을 알리려 했던 한 신자의 마지막 자리를 마주한다.', '신유박해(1801) 때 백서를 써 능지처참형을 받은 황사영 알렉시오가 묻힌 자리. 1980년 후손들이 무덤을 발견해 석제 십자가와 비단 조각이 담긴 항아리를 확인, 신원이 밝혀졌다.', '황사영 순교순례지 - 백서를 쓴 이의 마지막 자리', '경기도 양주시 홍복산, 신유박해 때 백서를 쓰고 순교한 황사영 알렉시오의 묘소. 1980년 유물 발견으로 신원이 밝혀진 순례지.', '치유', NULL, NULL),
  ('파티마평화의성당', '주교좌성당', '의정부', '경기', '경기도 파주시 문산읍 마정로 110', '파주 문산, 임진각에서 멀지 않은 자리에 거의 눈에 띄지 않는 특별한 성당이 있다. 휴전선과 가장 가까운 이 성당은 고도 제한 때문에 지상에 지을 수 없어 통째로 지하에 만들어졌다. 1982년부터 30여 년간 평화통일을 기원하는 성당을 세우려는 노력이 이어졌고, 후보지가 여러 번 바뀌었던 어려움 끝에 2015년 드디어 봉헌되었다. 티 없으신 마리아 성심 수녀회가 관리하는 이곳은 분단의 아픔을 품고 한반도의 평화를 기도하는 공간이다. 땅 아래 조용한 성전에서, 통일을 향한 오랜 염원과 마주한다.', '휴전선에서 가장 가까운 성당으로, 고도 제한 때문에 지하에 지어졌다. 1982년부터 30여 년간 추진되어 2015년 문을 열었으며 한반도 평화통일을 기원하는 기도의 공간이다.', '파티마평화의성당 - 땅 아래 지어진 평화의 기도', '경기도 파주시 문산읍, 휴전선에서 가장 가까운 지하 성당. 30여 년의 노력 끝에 2015년 봉헌된 한반도 평화통일 기원의 공간.', '평온', NULL, NULL);
