-- VisitHolyKorea: holy_sites 테이블 생성 + 66곳 데이터 삽입
-- Supabase SQL Editor에 전체 붙여넣고 실행하세요

create table if not exists public.holy_sites (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  category text,
  diocese text,
  region_province text,
  location text,
  description text,
  history text,
  image_url text,
  lat double precision,
  lng double precision,
  seo_title text,
  seo_description text,
  emotion_tag text,
  nearby_attractions text,
  nearby_lodging text,
  created_at timestamptz not null default now()
);

alter table public.holy_sites enable row level security;

drop policy if exists "holy_sites_public_read" on public.holy_sites;
create policy "holy_sites_public_read" on public.holy_sites
  for select using (true);


-- 확인용
select diocese, count(*) from public.holy_sites group by diocese order by count(*) desc;